const contractText = String.raw`PASTE_THE_EXACT_LAB_1_PRODUCTION_CONTRACT_JSON_HERE`;
if (contractText.startsWith('PASTE_')) throw new Error('Paste the exact Lab 1 production-contract.json into contractText.');
const contract=JSON.parse(contractText);
let fingerprint=0; for(const ch of contractText){fingerprint=(fingerprint*31+ch.charCodeAt(0))>>>0;}
return [{json:{...contract,source_fingerprint:`fnv31-${fingerprint.toString(16)}`,iteration:0}}];

const c=$input.first().json; const blockers=[];
if(c.run_id!=='HB-001') blockers.push('run_id_mismatch');
if(c.contract_version!=='contract-v1') blockers.push('contract_version_mismatch');
if(!c.source_fingerprint) blockers.push('missing_source_fingerprint');
if(!Array.isArray(c.approved_facts)||c.approved_facts.length===0) blockers.push('missing_approved_facts');
if(c.duration_seconds!==30) blockers.push('invalid_duration');
if(c.aspect_ratio!=='9:16') blockers.push('invalid_aspect_ratio');
if(c.publishing_mode!=='dry_run_private') blockers.push('unsafe_publishing_mode');
if(typeof c.cost_budget_sgd!=='number'||c.cost_budget_sgd<=0) blockers.push('generation_budget_missing');
return [{json:{...c,contract_valid:blockers.length===0,blockers}}];
